using System.Diagnostics;
using CatalogService.Data; using CatalogService.Models; using Microsoft.AspNetCore.Diagnostics; using Microsoft.EntityFrameworkCore;
var builder = WebApplication.CreateBuilder(args); builder.Logging.AddSimpleConsole(options => { options.SingleLine = true; options.TimestampFormat = "yyyy-MM-ddTHH:mm:ss.fffZ "; options.UseUtcTimestamp = true; }); builder.Services.AddDbContext<CatalogDbContext>(o => o.UseSqlServer(builder.Configuration.GetConnectionString("CatalogDb"))); builder.Services.AddControllers(); builder.Services.AddEndpointsApiExplorer(); builder.Services.AddSwaggerGen(); builder.Services.AddCors(o => o.AddDefaultPolicy(p => p.WithOrigins(builder.Configuration.GetSection("Cors:Origins").Get<string[]>() ?? []).AllowAnyHeader().AllowAnyMethod()));
var app = builder.Build(); var logger = app.Logger; app.UseExceptionHandler(errorApp => errorApp.Run(async context => { var exception = context.Features.Get<IExceptionHandlerFeature>()?.Error; logger.LogError(exception, "Unhandled exception. TraceId: {TraceId}; Method: {Method}; Path: {Path}", context.TraceIdentifier, context.Request.Method, context.Request.Path); await Results.Problem(statusCode: StatusCodes.Status500InternalServerError, title: "Ocurrió un error interno. Consulte el TraceId en los logs.").ExecuteAsync(context); })); app.UseSwagger(); app.UseSwaggerUI(); app.UseHttpsRedirection(); app.UseCors(); app.Use(async (context, next) => { var stopwatch = Stopwatch.StartNew(); using (logger.BeginScope(new Dictionary<string, object?> { ["TraceId"] = context.TraceIdentifier })) { logger.LogInformation("HTTP request started: {Method} {Path}", context.Request.Method, context.Request.Path); try { await next(); logger.LogInformation("HTTP request completed: {Method} {Path} responded {StatusCode} in {ElapsedMs} ms", context.Request.Method, context.Request.Path, context.Response.StatusCode, stopwatch.ElapsedMilliseconds); } catch (Exception exception) { logger.LogError(exception, "HTTP request failed: {Method} {Path} after {ElapsedMs} ms", context.Request.Method, context.Request.Path, stopwatch.ElapsedMilliseconds); throw; } } }); app.MapControllers();
using (var scope = app.Services.CreateScope()) { var db = scope.ServiceProvider.GetRequiredService<CatalogDbContext>(); await db.Database.EnsureCreatedAsync(); if (!await db.Products.AnyAsync()) { db.Products.AddRange(new Product { Slug="vela-ambar", Name="Vela Ámbar", Price=480, Existencia=12, Category="Aromas", ImageUrl="https://images.unsplash.com/photo-1603006905003-be475563bc59?auto=format&fit=crop&w=700&q=85", Description="Cera vegetal y notas cálidas de ámbar." }, new Product { Slug="taza-arena", Name="Taza Arena", Price=290, Existencia=8, Category="Mesa", ImageUrl="https://images.unsplash.com/photo-1514228742587-6b1558fcca3d?auto=format&fit=crop&w=700&q=85", Description="Cerámica esmaltada hecha para las pausas largas." }); await db.SaveChangesAsync(); } }
app.Run(); public partial class Program { }
